import React from 'react';
import  '../Shared/CallerModel.css';

const CallerModal = ({ callerData}) => {
    if (!callerData) return null;

    const getInitials = (name) => {
        if (!name) return '';
        const parts = name.split(' ');
        return parts.length === 1
            ? parts[0].charAt(0).toUpperCase()
            : (parts[0].charAt(0) + parts[1].charAt(0)).toUpperCase();
    };

    return (
        <div className="call-modal-overlay">
            <div className="call-modal">
                <div className="circle-animation-wrapper">
                    <div className="circle-pulse">
                        <span className="caller-initials">
                            {getInitials(callerData.userName)}
                        </span>
                    </div>
                </div>
                <h4>Callinng</h4>
                {callerData.userName}
                <div className="call-modal-actions">
                    <button className="btn accept-btn">Accept</button>
                    <button className="btn decline-btn">Decline</button>
                </div>
            </div>
        </div>
    );
};

export default CallerModal;