// /client/src/components/Shared/Header.jsx
import React, { useEffect, useState,useContext } from 'react';
import { useForm } from 'react-hook-form';
import 'bootstrap/dist/css/bootstrap.min.css';
import axios from 'axios';
import { useLocation } from 'react-router-dom';
import * as apiService from '../../services/userService';
import { UserContext } from "../Shared/UserContext";
import { v4 as uuidv4 } from 'uuid';
import { startConnection, sendMessageSignalR } from '../../services/userService';

const Header = ({ callToReceiver ,onIncomingCall,callerUser}) => {
  const location = useLocation();
  //const { register, handleSubmit } = useForm();
  const [userName, setUserName] = useState("");
  const [user, setUser] = useState(null);
  const { loginUser, setLoginUser } = useContext(UserContext);
  const [callingReceiver, setCallToReceiver] = useState(null);

  useEffect(() => {
    const loggedUser = location.state?.email;
    
    const fetchUser = async () => {
      if (!loggedUser) return;
      const result = await apiService.getUser(loggedUser);
      if (result.success) {
            setUserName(result.username); // ✅ updates state, triggers re-render
            setLoginUser(result.username);
            setUser(result);

            //hub
            const hubConn = await startConnection(result.id);

            hubConn.on("ReceiveCall", (callDetails) => {
                console.log("Incoming call:", callDetails);
                if (callDetails) {
                    onIncomingCall(callDetails); // ✅ pass to Dashboard
                }
            });
      }
    };

    fetchUser(); 
  },[]);

  useEffect(() => {
    if (callToReceiver) {
      setCallToReceiver(callToReceiver);
    }
  }, [callToReceiver]);

  const handleCall = async (type) => {
    if (!callToReceiver || !loginUser) {
      alert("Please select a user to call.");
      return;
    }
    const roomId = uuidv4(); // unique call room ID
    var callData ={
      CallerId:user.id,
      ReceiverId:callToReceiver.id,
      RoomId:roomId,
      CallType:type
    }

    const response = await apiService.startCallSession(callData);
    if (!response.status) {
      alert("Failed to start call.");
      return;
    }
    else{
      callerUser(callToReceiver);
    }
  };

  return (
    <div className="d-flex justify-content-between align-items-center bg-primary text-white px-4 py-2 shadow-sm">
      {/* Left: Profile + Status */}
      <div className="d-flex align-items-center gap-3">
        <strong>{userName || 'Loading...'}</strong>
      </div>

      {/* Right: Call Buttons */}
      <div className="d-flex gap-2">
        <button className="btn btn-outline-light btn-sm" onClick={() => handleCall('video')}>
          <i className="bi bi-camera-video-fill me-1"></i> Video Call
        </button>
        <button className="btn btn-outline-light btn-sm" onClick={() => handleCall('audio')}>
          <i className="bi bi-telephone-fill me-1"></i> Audio Call
        </button>
      </div>
    </div>
  );
};

export default Header;